transforms.code:
if ']' in value:
	# Tag provider is in the path, remove it.
	tagPath = value.split(']')[1]
else:
	tagPath = value

return '*{tagPath}*'.format(tagPath = tagPath)

return [
	  {
	    "aggregate": "LastValue",
	    "alias": "ACTIVE POWER TOTAL",
	    "color": "var(--qual-7)",
	    "path": "{tagPath}/Power/ActivePowerTotal".format(tagPath = value)
	  },
	  {
	    "aggregate": "LastValue",
	    "alias": "APPARENT POWER TOTAL",
	    "color": "var(--qual-10)",
	    "path": "{tagPath}/Power/ApparentPowerTotal".format(tagPath = value)
	  }
	]
